import{_ as t,c as a,o,ae as r}from"./chunks/framework.ixH79I-5.js";const m=JSON.parse('{"title":"Frequently Asked Questions (FAQs)","description":"FAQs","frontmatter":{"title":"Frequently Asked Questions (FAQs)","description":"FAQs"},"headers":[],"relativePath":"general/frequently_asked_questions.md","filePath":"general/frequently_asked_questions.md"}'),n={name:"general/frequently_asked_questions.md"};function s(i,e,l,h,d,u){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="frequently-asked-questions-faqs" tabindex="-1">Frequently Asked Questions (FAQs) <a class="header-anchor" href="#frequently-asked-questions-faqs" aria-label="Permalink to &quot;Frequently Asked Questions (FAQs)&quot;">​</a></h1><h3 id="how-do-i-install-betterkmr" tabindex="-1">How do I install BetterKMR? <a class="header-anchor" href="#how-do-i-install-betterkmr" aria-label="Permalink to &quot;How do I install BetterKMR?&quot;">​</a></h3><p>Installing BetterKMR is easy! You can download the latest version from both the Chrome Web Store and Firefox Add-ons. To install BetterKMR manually, you can download the latest release from the releases page.</p><h3 id="why-can-t-i-add-external-javascript-code-to-my-custom-theme" tabindex="-1">Why can&#39;t I add external JavaScript code to my custom theme? <a class="header-anchor" href="#why-can-t-i-add-external-javascript-code-to-my-custom-theme" aria-label="Permalink to &quot;Why can&#39;t I add external JavaScript code to my custom theme?&quot;">​</a></h3><p>Due to security concerns, this feature is not yet available, but is possibly planned.</p><h3 id="the-navbar-doesn-t-work-well-with-my-school-s-kamar-page" tabindex="-1">The navbar doesn&#39;t work well with my school&#39;s Kamar page? <a class="header-anchor" href="#the-navbar-doesn-t-work-well-with-my-school-s-kamar-page" aria-label="Permalink to &quot;The navbar doesn&#39;t work well with my school&#39;s Kamar page?&quot;">​</a></h3><p>This is a known issue and we&#39;re working on it. For now though, you can toggle the Dynamic Navbar option in the settings. Check the question below to join our Discord server.</p><h3 id="i-m-having-trouble-with-betterkmr-where-can-i-get-help" tabindex="-1">I&#39;m having trouble with BetterKMR, where can I get help? <a class="header-anchor" href="#i-m-having-trouble-with-betterkmr-where-can-i-get-help" aria-label="Permalink to &quot;I&#39;m having trouble with BetterKMR, where can I get help?&quot;">​</a></h3><p>You can join the Discord server to get help from the developers.</p><h3 id="why-doesn-t-the-extension-work-properly-when-i-download-the-zip-from-the-main-branch" tabindex="-1">Why doesn&#39;t the extension work properly when I download the .zip from the main branch? <a class="header-anchor" href="#why-doesn-t-the-extension-work-properly-when-i-download-the-zip-from-the-main-branch" aria-label="Permalink to &quot;Why doesn&#39;t the extension work properly when I download the .zip from the main branch?&quot;">​</a></h3><p>This is because the intention of BetterKMR is to be built before it can be actually used. You can either:</p><ul><li>Get BetterKMR from the Chrome Web Store (recommended).</li><li>Use the prebuilt versions from the releases page or the GitHub workflow runs for cutting-edge development builds.</li><li>Build BetterKMR yourself. You can find the instructions at the &quot;Building &amp; Developing&quot; section in Guides.</li></ul>',12)]))}const p=t(n,[["render",s]]);export{m as __pageData,p as default};
